#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node *left, *right, *parent;
} Node;

Node *node_new(int key) {
    Node *x = malloc(sizeof(Node));
    x->key = key;
    x->left = x->right = x->parent = NULL;
    return x;
}

void bst_insert(Node **root, Node *z) {
    Node *y = NULL, *x = *root;
    while (x != NULL) {
        y = x;
        x = (z->key < x->key) ? x->left : x->right;
    }
    z->parent = y;
    if (y == NULL) *root = z;
    else if (z->key < y->key) y->left = z;
    else y->right = z;
}

Node *bst_search(Node *x, int key) {
    while (x != NULL && key != x->key)
        x = (key < x->key) ? x->left : x->right;
    return x;
}

Node *bst_minimum(Node *x) {
    while (x->left != NULL) x = x->left;
    return x;
}

/* replaces the subtree rooted at u with the subtree rooted at v */
void transplant(Node **root, Node *u, Node *v) {
    if (u->parent == NULL) *root = v;
    else if (u == u->parent->left) u->parent->left = v;
    else u->parent->right = v;
    if (v != NULL) v->parent = u->parent;
}

void bst_delete(Node **root, Node *z) {
    if (z->left == NULL)
        transplant(root, z, z->right);
    else if (z->right == NULL)
        transplant(root, z, z->left);
    else {
        Node *y = bst_minimum(z->right);      /* inorder successor */
        if (y->parent != z) {
            transplant(root, y, y->right);
            y->right = z->right;
            y->right->parent = y;
        }
        transplant(root, z, y);
        y->left = z->left;
        y->left->parent = y;
    }
    free(z);
}

void inorder(Node *x) {
    if (x == NULL) return;
    inorder(x->left);
    printf("%d ", x->key);
    inorder(x->right);
}

int main(void) {
    Node *root = NULL;
    int keys[] = {15, 6, 18, 3, 7, 17, 20, 2, 4, 13, 9};
    int n = sizeof(keys) / sizeof(keys[0]);
    for (int i = 0; i < n; i++)
        bst_insert(&root, node_new(keys[i]));

    printf("inorder: ");
    inorder(root);
    printf("\n");

    bst_delete(&root, bst_search(root, 6));   /* two children, successor is z's right child */
    printf("after deleting 6: ");
    inorder(root);
    printf("\n");
    return 0;
}
